MOD = 998244353

def factorial_mod(n, mod):
    result = 1
    for i in range(2, n + 1):
        result = (result * i) % mod
    return result

def mod_inverse(x, mod):
    return pow(x, mod - 2, mod)

def count_good_permutations(n, s):
    if n <= 1:
        return 1

    # Check if the sequence is already good
    a_sorted = sorted(a for a, b in s)
    b_sorted = sorted(b for a, b in s)

    if a_sorted == list(range(1, n + 1)) or b_sorted == list(range(1, n + 1)):
        return 0

    # Count the occurrences of each number in the sequence
    a_count = [0] * (n + 1)
    b_count = [0] * (n + 1)

    for a, b in s:
        a_count[a] += 1
        b_count[b] += 1

    # Calculate the number of permutations of the sequence
    perm_count = factorial_mod(n, MOD)

    # Divide by the factorial of the counts of each number
    for count in a_count[1:]:
        if count > 0:
            perm_count = (perm_count * mod_inverse(factorial_mod(count, MOD), MOD)) % MOD

    for count in b_count[1:]:
        if count > 0:
            perm_count = (perm_count * mod_inverse(factorial_mod(count, MOD), MOD)) % MOD

    return perm_count

