import sys
from itertools import permutations

MOD = 998244353

def count_good_permutations(n, sequence):
    def is_good_sequence(seq):
        first_elements_sorted = all(seq[i][0] <= seq[i+1][0] for i in range(len(seq) - 1))
        second_elements_sorted = all(seq[i][1] <= seq[i+1][1] for i in range(len(seq) - 1))
        return not (first_elements_sorted or second_elements_sorted)

    good_count = 0

    for perm in permutations(range(n)):
        permuted_sequence = [sequence[i] for i in perm]
        if is_good_sequence(permuted_sequence):
            good_count += 1
            good_count %= MOD

    return good_count

def main():
    input = sys.stdin.readline
    n = int(input().strip())
    sequence = [tuple(map(int, input().strip().split())) for _ in range(n)]

    result = count_good_permutations(n, sequence)
    print(result)

if __name__ == "__main__":
    main()
